{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C03"],
      "claim": "Imatinib, which shares the piperazine and aminopyrimidine aniline motif with the query, has a mean absolute oral bioavailability of 98% in humans, supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C32"],
      "claim": "GSK1322322, a piperazine-containing oral drug with an aminopyrimidine aniline substructure, showed 77% absolute bioavailability in healthy volunteers after a fed dose, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C16"],
      "claim": "Brepocitinib, a heteroaromatic oral kinase inhibitor, had an estimated absolute bioavailability of 75% in humans, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C31"],
      "claim": "Niraparib, an oral heteroaromatic drug, had an absolute bioavailability of 72.7% in patients, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C18"],
      "claim": "Trametinib, a fused heteroaromatic oral drug, had an absolute bioavailability of 72.3% in patients with solid tumours, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C22"],
      "claim": "The closest structural analogue (Morgan 0.375) has an oral bioavailability of approximately 20–25%, which meets the F ≥ 20% threshold and does not affirmatively indicate low F.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a drug-like heteroaromatic oral compound containing a piperazine and aminopyrimidine aniline motif. Multiple transferable experimental records for structurally related oral drugs (imatinib 98%, GSK1322322 77%, brepocitinib 75%, niraparib 72.7%, trametinib 72.3%, risdiplam high) consistently support F ≥ 20%. The closest analogue is borderline (~20–25%) but still meets the threshold. No affirmative evidence supports F < 20%. Therefore predict high.",
  "evidence_gaps": [
    "No direct absolute bioavailability measurement exists for the exact query molecule.",
    "Morgan similarities are low to moderate (0.22–0.38), limiting direct transferability.",
    "The closest analogue's F is borderline (~20–25%), so the margin above the threshold is uncertain.",
    "No specific data on solubility, permeability, first-pass metabolism, or transporter effects for the query scaffold."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

